warnings.filterwarnings('ignore', category=RuntimeWarning)

def sampled_row_alignment(df):
    counts = df['cls'].value_counts().to_dict()
    # load() is the original implementation. The in-memory file stand-in holds wafer IDs.
    class FakeFile(dict):
        def __enter__(self): return self
        def __exit__(self, *args): return False
    def fake_load(path, **kw):
        c = Path(path).stem
        return FakeFile(wafer_maps=np.arange(counts[c]))
    rng = np.random.default_rng(config.SEED)
    with patch.object(feature_table.np, 'load', side_effect=fake_load):
        sampled = {c: feature_table.load(c, rng=rng) for c in config.PATTERN_CLASSES}
        count_sample = {c: feature_table.load(c, rng=np.random.default_rng(config.SEED))
                        for c in ('Edge-Loc', 'Edge-Ring')}
    mismatch = {c: int((sampled[c] != count_sample[c]).sum()) for c in count_sample}
    # features.csv retains the original per-class row order used by load().
    F = {c: df[df.cls == c].reset_index(drop=True) for c in count_sample}
    sizes = {c: F[c].map_size.to_numpy()[sampled[c]] for c in F}
    aligned = {c: F[c].n_fail.to_numpy()[sampled[c]] for c in F}
    wrong = {c: F[c].n_fail.to_numpy()[count_sample[c]] for c in F}
    edges = np.percentile(np.r_[sizes['Edge-Loc'], sizes['Edge-Ring']], [0,25,50,75,100])
    rows = []
    for lo, hi in zip(edges[:-1], edges[1:]):
        mask = {c: (sizes[c] >= lo) & (sizes[c] < hi) for c in F}
        rows.append({'lo': lo, 'hi': hi,
                     'unaligned_auc': azimuth.auc(wrong['Edge-Ring'][mask['Edge-Ring']], wrong['Edge-Loc'][mask['Edge-Loc']]),
                     'aligned_auc': azimuth.auc(aligned['Edge-Ring'][mask['Edge-Ring']], aligned['Edge-Loc'][mask['Edge-Loc']])})
    return {'mismatch': mismatch, 'rows_per_class': 2500, 'strata': rows,
            'identity_assumption': 'features.csv is ordered by original class-local wafer order, as exported idx indicates'}

observed = sampled_row_alignment(pd.read_csv('data/features.csv'))
print(json.dumps(observed, ensure_ascii=False, indent=2))
